"""Measure the adopted Microsoft whole-sentence recordings; no network calls."""
from pathlib import Path
import hashlib,json,math,re,subprocess
ROOT=Path(__file__).resolve().parents[3];F=ROOT/'arts/actions/film';P=F/'provenance/voice-v13';OUT=ROOT/'arts/audio/film/voice-v13'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
 alignment=json.loads((P/'alignment.json').read_text());provider=json.loads((P/'provider.json').read_text());cues=json.loads((F/'captions-v01.json').read_text());old=json.loads((P/'expansion-estimate.json').read_text())
 assert ''.join(c['text']for c in cues)==''.join(s['text']for s in alignment['sentences'])
 rows=[];recordings=[]
 for chapter in alignment['chapters']:
  ss=[s for s in alignment['sentences']if s['chapterId']==chapter['id']];clip_seconds=flow_seconds=0
  for s in ss:
   p=OUT/'sentences'/f'{s["id"]}.wav';probe=json.loads(subprocess.check_output(['/opt/homebrew/bin/ffprobe','-v','error','-show_streams','-of','json',str(p)]));stream=probe['streams'][0];seconds=int(stream['duration_ts'])/48000
   assert abs(seconds-(s['speechEnd']-s['start']))<1/48000
   request=ROOT/s['rawPath'];payload=json.loads(request.with_suffix('.request.json').read_text());assert payload['voice']==provider['voice']and payload['rate']==provider['rate']and payload['pitch']==provider['pitch']
   duration=s['end']-s['start']
   if s==alignment['sentences'][-1]:duration=math.ceil((seconds+.62)*30-1e-7)/30
   clip_seconds+=seconds;flow_seconds+=duration
   recordings.append(dict(id=s['id'],path=str(p.relative_to(ROOT)),sha256=sha(p),rawPath=s['rawPath'],rawSha256=sha(request),samples=int(stream['duration_ts']),clipSeconds=seconds,flowSeconds=duration))
  text=''.join(s['text']for s in ss);characters=len(re.sub(r'\s','',text));han=len(re.findall('[\u4e00-\u9fff]',text));gap=next(r['shortfallSeconds']for r in old['chapters']if r['chapter']==chapter['id'])
  rows.append(dict(chapter=chapter['id'],sentences=len(ss),characters=characters,chineseCharacters=han,clipSeconds=clip_seconds,flowSeconds=flow_seconds,clipCharactersPerMinute=characters/clip_seconds*60,flowCharactersPerMinute=characters/flow_seconds*60,flowChineseCharactersPerMinute=han/flow_seconds*60,shortfallSeconds=gap,additionalChineseCharactersWithNormalPauses=round(gap*han/flow_seconds)))
 chars=sum(r['characters']for r in rows);han=sum(r['chineseCharacters']for r in rows);clip=sum(r['clipSeconds']for r in rows);flow=sum(r['flowSeconds']for r in rows)
 assert chars==994 and han==860
 totals=dict(sentences=len(recordings),characters=chars,chineseCharacters=han,clipSeconds=clip,flowSeconds=flow,normalSentenceGapSeconds=flow-clip,clipCharactersPerMinute=chars/clip*60,flowCharactersPerMinute=chars/flow*60,clipChineseCharactersPerMinute=han/clip*60,flowChineseCharactersPerMinute=han/flow*60,additionalChineseCharactersWithNormalPauses=sum(r['additionalChineseCharactersWithNormalPauses']for r in rows))
 report=dict(version='NARRATION_SPEED_CALIBRATION v0.1',date='2026-10-21',provider=provider,scope='Adopted whole-sentence v13 voice, rate=-5%; not a measured claim about Microsoft default rate=0% or other voices.',oldEstimate=dict(value=220,unit='non-whitespace Unicode characters per minute',secondsUnitWasIncorrect=True),definitions=dict(characters='Unicode code points excluding whitespace, including punctuation, Latin letters and digits; the same count basis as the old220 estimate.',chineseCharacters='Han characters only; punctuation, Latin letters and digits excluded.',clipSeconds='Independently probed WAV sample counts for28 trimmed sentence clips. Native internal pauses retained; includes short external safety pads, excludes added between-sentence gaps and visual holds.',flowSeconds='Measured clip lengths plus adopted normal between-sentence gaps (about0.5s, slightly longer at chapter ends), rounded to30fps. The artificial closing-life extension, entry adapters and reference pages are excluded. This is a planning statistic, not solely model-generated timing.'),totals=totals,chapters=rows,planning=dict(charactersPerMinute=300,chineseCharactersPerMinute=260,observedChapterRangeCharactersPerMinute=[min(r['flowCharactersPerMinute']for r in rows),max(r['flowCharactersPerMinute']for r in rows)],formula='narration_flow_seconds = non_whitespace_characters /300 *60; add separately required visual-only holds. Do not add ordinary sentence pauses a second time.',originalFilmDurationSeconds=280,doNotRetimeFilmAutomatically=True,legacy1100CharacterCap='Preserve as an independent recorded content constraint; recalibrating speed does not automatically expand this cap.'),recordings=recordings,inputs=[dict(path=str(p.relative_to(ROOT)),sha256=sha(p))for p in [P/'alignment.json',P/'provider.json',F/'captions-v01.json',Path(__file__).resolve()]])
 (P/'speed-calibration.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n')
 table='\n'.join(f'| {r["chapter"]} | {r["characters"]} | {r["chineseCharacters"]} | {r["clipSeconds"]:.2f} | {r["flowSeconds"]:.2f} | {r["flowCharactersPerMinute"]:.1f} |'for r in rows)
 text=f'''# 旁白语速校准\n\n版本：NARRATION_TIMING v0.1 · 2026-10-21\n\n当前项目采用微软云扬`zh-CN-YunyangNeural`，`rate=-5%`、`pitch=-2Hz`。以下为本项目28个完整语句的实测，不代表微软所有声音或默认`rate=0%`的统一速度。本轮只读取本地录音，无新TTS请求。\n\n## 采用值与计数\n\n旧计划为220字符／分钟，单位不是每秒。后续本项目改用约**300非空白字符／分钟**，或约**260汉字／分钟**。两种计数不能混用：前者计入标点、英文字母和数字，后者只计汉字。Agent等英文的发音时间已经包含在样本中，英文比例明显变化时重新合成测时。\n\n- 28段句子WAV：{chars}个非空白字符／{han}个汉字，{clip:.2f}秒，约{totals['clipCharactersPerMinute']:.1f}字符／分钟，或{totals['clipChineseCharactersPerMinute']:.1f}汉字／分钟。保留句内自然停顿和短静音安全边，未把每个音素之间的静音剔除。\n- 再计入正常句末和章末换气：{flow:.2f}秒，约{totals['flowCharactersPerMinute']:.1f}字符／分钟，或{totals['flowChineseCharactersPerMinute']:.1f}汉字／分钟。正常句间停顿为已采用的排时设置，因此这是用于编剧的排时口径，并非全部由微软模型自动产生。\n- 章间实测排时范围约280–310字符／分钟。规划采用300，新增或大改稿仍需实际合成后逐句校时。\n\n| 章 | 全部非空白字符 | 汉字 | 语句音频秒数 | 含正常句间停顿秒数 | 排时字符／分钟 |\n|---|---:|---:|---:|---:|---:|\n{table}\n| 合计 | {chars} | {han} | {clip:.2f} | {flow:.2f} | {totals['flowCharactersPerMinute']:.1f} |\n\n## 使用规则\n\n预计口播流时长（秒）＝非空白字符数÷300×60。只有汉字统计时可暂用汉字数÷260×60；二者只选一种。上述速度已含正常句间停顿，不再额外重复添加同一换气时间。文献卡、明确需要的操作／读图和生活留白另外登记，不能把完整视频或280秒WAV里的长静音当成配音速度。\n\n当前994字符用新规则约需198.8秒；样本含正常换气实测为{flow:.2f}秒。v13全片候选223.73秒还含独立的片头接续、结尾生活留白与14秒文献页，不能拿994÷223.73替代自然口播语速。\n\n原4分40秒和六章45／38／39／55／45／58秒预算保留。语速校准不授权缩短画面或改写人工口播。此前约262汉字的补稿估算只用语句音频速度；若新增段落也安排正常换气，按各章排时速度约需**{totals['additionalChineseCharactersWithNormalPauses']}汉字**，是规划近似，取决于新增句数和英文比例；此前245–275字可作较紧凑叙述的范围。\n\n旧《创作任务书》记录的1100字符上限作为独立约束保留，不因速度改为300而自动增至1500。当前994字符距该上限只剩106字符；如需按约240–260汉字扩稿并保持280秒，应先明确如何处理该既有上限。本轮只修订估算规则，不扩写正文。\n\n## 证据与复现\n\n完整口径、28段样本数／SHA、逐章数据和输入哈希见[机器可读统计](../../arts/actions/film/provenance/voice-v13/speed-calibration.json)。命令：`python3 arts/actions/film/calibrate-narration-speed.py`，仅依赖本地Python与`/opt/homebrew/bin/ffprobe`。\n'''
 (ROOT/'scripts/style/NARRATION_TIMING.md').write_text(text)
 print(json.dumps(dict(totals=totals,planning=report['planning']),ensure_ascii=False,indent=2))
if __name__=='__main__':main()
